@Component("visualization-handler")
@ProcessingGroup("visualization-processing-group")
public class VisualizationEventHandler {
	
	// core constructor
	VisualizationEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateVisualizationEvent
     */
    @EventHandler
    public void handle( CreateVisualizationEvent event) {
        entityManager.persist(new Visualization(event.getVisualizationId(), event.getTitle(), event.getOptions(), event.getDashboard(), event.getReport(), event.getMetrics(), event.getDimensions(), event.getDatasets(), event.getChartType()));
    }

    /*
     * @param	event UpdateVisualizationEvent
     */
    @EventHandler
    public Visualization handle( UpdateVisualizationEvent event) {
    	entityManager.merge(new Visualization(event.getVisualizationId(), event.getTitle(), event.getOptions(), event.getDashboard(), event.getReport(), event.getMetrics(), event.getDimensions(), event.getDatasets(), event.getChartType()));
    }
    
    /*
     * @param	event DeleteVisualizationEvent
     */
    @EventHandler
    public void on( DeleteVisualizationEvent event) {
    	Visualization entity = new Visualization();
   
    	// ------------------------------------------
    	// apply the VisualizationId
    	// ------------------------------------------
    	entity.setVisualizationId( event.getVisualizationId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final VisualizationRepository visualizationEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(VisualizationEventHandler.class.getName());

}
